def parse_endpoint_host(value):
    # ep/ci 的 host：无区域标识（不含 %）的 IP 字面量，且规范化形式与
    # 原文逐字节相同（拒绝前导零、非常规缩写等写法）；非字符串、非
    # IP 字面量或含区域标识均判 INPUT。
    if not isinstance(value, str) or "%" in value:
        fail(EXIT_INPUT, "INPUT")
